    cin >> n;
    vector<long long> arr(n);
    for (auto &x : arr) cin >> x;
    long long k;
    cin >> k;

    const int INF = INT_MAX;
    vector<int> dp(k + 1, INF);
    dp[0] = 0;
    for (long long a = 1; a <= k; a++)
        for (auto c : arr)
            if (c <= a && dp[a - c] != INF) dp[a] = min(dp[a], dp[a - c] + 1);
    cout << (dp[k] == INF ? -1 : dp[k]) << "\n";

    return 0;
}

