        while (ptr < input.length && input[ptr] > ' ') ptr++;
        return new String(input, start, ptr - start);
    }

    public static void main(String[] args) throws IOException {
        input = System.in.readAllBytes();
        int n = Integer.parseInt(next());
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) arr[i] = Long.parseLong(next());
        long k = Long.parseLong(next());

        int amount = (int) k;
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (long c : arr)
                if (c <= a && dp[a - (int) c] != Integer.MAX_VALUE) dp[a] = Math.min(dp[a], dp[a - (int) c] + 1);
        System.out.println(dp[amount] == Integer.MAX_VALUE ? -1 : dp[amount]);
    }
}

