        for (int i = 0; i < r; i++) g[i] = next().toCharArray();

        int islands = 0;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                if (g[i][j] != '1') continue;
                islands++;
                g[i][j] = '0';
                q.add(new int[] {i, j});
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    for (int d = 0; d < 4; d++) {
                        int nx = cur[0] + dr[d], ny = cur[1] + dc[d];
