#include <deque>
#include <climits>
#include <functional>
using namespace std;

long long solveQueens(int row, int n, int cols, int d1, int d2) {
    if (row == n) return 1;
    long long total = 0;
    for (int c = 0; c < n; c++) {
        int a = 1 << c, b = 1 << (row + c), d = 1 << (row - c + n - 1);
        if ((cols & a) || (d1 & b) || (d2 & d)) continue;
        total += solveQueens(row + 1, n, cols | a, d1 | b, d2 | d);
    }
    return total;
}

